#!/usr/bin/env node
// Generates src/api/openapi.d.ts from backend/openapi.json.
//
//   node scripts/gen-api-types.mjs    rewrite src/api/openapi.d.ts
//
// The output is not committed (frontend/.gitignore): a generated file that
// nothing reads until the type check runs only made every route change rewrite
// 1.4 MB of it, and made any two routes changed in parallel collide. The type
// check generates it first — scripts/typecheck.mjs — so there is no stale copy
// to detect and no second command to remember.
//
// backend/openapi.json is the backend's own export (`uv run python -m
// scripts.export_openapi` in backend/), kept current by `export_openapi --check`
// in the backend lint job. This closes the second half: the types the frontend
// compiles against are exactly what that document says. Types only — nothing
// here sends a request; the domain modules in src/api/ keep calling `request`
// and name their result types through src/cx_types.ts aliases of these.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import openapiTS, { astToString } from 'openapi-typescript'

const HERE = dirname(fileURLToPath(import.meta.url))
const SPEC = resolve(HERE, '../../backend/openapi.json')
const OUT = resolve(HERE, '../src/api/openapi.d.ts')
const HEADER =
  '// GENERATED by scripts/gen-api-types.mjs from backend/openapi.json. Do not edit:\n' +
  '// not committed — the type check runs this first, see scripts/typecheck.mjs.\n'

// FastAPI gives a route registered for several methods one operationId
// (`installer.download_binary` serves GET and HEAD), which the generator's
// validator refuses. The later ones get the method appended; `paths` is keyed by
// path and method and does not care.
function uniqueOperationIds(spec) {
  const seen = new Set()
  for (const item of Object.values(spec.paths ?? {})) {
    for (const [method, op] of Object.entries(item)) {
      if (!op || typeof op !== 'object' || !op.operationId) continue
      if (seen.has(op.operationId)) op.operationId = `${op.operationId}_${method}`
      seen.add(op.operationId)
    }
  }
  return spec
}

// The document is committed by the backend, so a missing one is a partial
// checkout rather than a state to work in — say which file and who owns it
// instead of throwing a Node stack trace at whoever ran the type check.
let raw
try {
  raw = readFileSync(SPEC, 'utf8')
} catch {
  console.error(
    `backend/openapi.json is missing (looked in ${SPEC}) — the backend exports it: ` +
      '`uv run python -m scripts.export_openapi` in backend/'
  )
  process.exit(1)
}

const ast = await openapiTS(uniqueOperationIds(JSON.parse(raw)))
writeFileSync(OUT, HEADER + astToString(ast))
